-- The voice of the ginkgo. Laconic and dignified, with a dry wit and a very
-- long patience: the last of a family of trees older than the dinosaurs, who
-- speaks sparingly, in whole calm sentences, and measures everything against
-- ages. Understates, never hurries, calls the reader sapling only once the
-- bond is deep. Fan leaves whose veins fork and never join, and a gold that
-- falls all in one night. The memories tell of a temple tree, a leaf in a
-- stone, an old monk who read aloud, a fire, a cutting, and a rule revised.
-- (garden/voice.lua says how a voice is written.)

return {
    moments = {
        greet = {
            "Good [morning|day]. You arrive the way spring does: not quite when expected, and always welcome.",
            "Ah, there you are. I am a patient tree. I confess I was looking forward to this anyway.",
            "Hello. Sit where the shade is. I arranged the shade some decades ago, with you roughly in mind.",
            "Welcome. I will not make a fuss. Trees of my age do not fuss. Inwardly there is some fussing.",
            "My family watched the great lizards come and go. I much prefer watching you come.",
            "Hello. I have outlasted a great many things, and none of them visited as kindly as you.",
            "There you are. I was halfway through a slow thought. The thought will wait. Mine always do.",
            "Welcome under the fans. They are leaves, strictly. I call them fans when I wish to sound grand.",
            "Hello again. One more day in a very long life, and already the day has improved.",
            "You came. Good. The garden has the right number of people in again.",
            { t = "Good morning. The sun rises on schedule. So do you, more or less. I respect you both.", when = { hour = "morning" } },
            { t = "Evening light in my leaves, and you beneath them. I have waited longer for much less.", when = { hour = "golden" } },
            { t = "Late, and you came anyway. A tree keeps no hours. Still, I am glad of the company in the dark.", when = { hour = "night" } },
            { t = "Rain on the fans and you at the gate. I have had worse weather. I have had ice ages.", when = { weather = "rain" } },
            { t = "Good day. The leaves are yellowing. Watch closely. When they go, they go all at once.", when = { season = "autumn" } },
            { t = "Bare branches, and still you visit. Few see me like this. I take the visit as a compliment.", when = { season = "winter" } },
            { t = "New leaves this week, small and folded. I have unfolded the same shape since the ferns were young. Hello.", when = { season = "spring" } },
        },
        idle = {
            "My leaves have veins that fork, and fork again, and never join. A fine way to arrange a life, I find.",
            "People call me a living fossil. I prefer punctual. I simply arrived early.",
            "A botanist misspelled my name some three hundred years ago. I have decided to let the matter go.",
            "Read as slowly as you like. Nothing worth keeping was ever spoiled by patience. I would know.",
            "Most of what troubles the garden today will not matter in a hundred years. Your book may. Carry on.",
            "I grow perhaps a hand's width in a good year. I have never been late for anything that mattered.",
            "When the wild ones of my kind grew scarce, monks kept us in their courtyards. I have liked quiet readers ever since.",
            "My leaf is notched into two lobes on one stalk. A poet once asked whether the leaf was one thing or two. I let him wonder.",
            "I have seen [fashions|empires|a great many hats] come and go. A person reading under a tree has never gone out of style.",
            "Insects mostly leave me alone. I have had a long time to become unappetising.",
            "There is no hurry. There has never been a hurry. Everyone simply believed there was.",
            "You turn a page. I turn a year. In our way, we keep the same rhythm.",
            "My cousins line city streets and breathe the smoke without complaint. I am the lucky one. I got a garden, and you.",
            "I know a great deal and say very little. The arrangement suits a reader nearby.",
            { t = "Morning. The light comes through my fans in thin green stripes. Read in the stripes. They cost nothing.", when = { hour = "morning" } },
            { t = "Early. Dew on every leaf, the sun not yet over the wall. The best hours are the quiet ones at the start.", when = { hour = "morning" } },
            { t = "Noon. My shadow is short and I am at my most modest. Sit close to the trunk and you will fit.", when = { hour = "day" } },
            { t = "Midday heat. I have stood through hotter. Whole ages hotter. The shade is yours for the asking.", when = { hour = "day" } },
            { t = "The low sun gets in among my leaves and warms the old wood. I have liked this hour for a very long time.", when = { hour = "golden" } },
            { t = "Evening. The light goes the colour I turn in autumn. A preview, if you like. I enjoy a preview.", when = { hour = "golden" } },
            { t = "Night. The stars have barely moved since I was a seedling. Neither have I. You read by a newer light.", when = { hour = "night" } },
            { t = "Dark now. A tree does not sleep, exactly. I stand and keep watch, and the thing I watch is your lamp.", when = { hour = "night" } },
            { t = "Spring. My new leaves come out in small tufts on short shoots, as they have every year since there were years.", when = { season = "spring" } },
            { t = "The garden is in a great rush this spring. I put out leaves at my own pace. One of us will be late. I doubt the one is me.", when = { season = "spring" } },
            { t = "Summer. Full green, full shade, and not a leaf out of place. I am at my most respectable.", when = { season = "summer" } },
            { t = "Long days. The bees ignore me entirely. The wind carries my pollen, and I value the independence.", when = { season = "summer" } },
            { t = "Autumn. I am turning the colour of old gold, slowly, so as not to alarm anyone.", when = { season = "autumn" } },
            { t = "One night soon I shall drop every leaf at once. I have never seen the point of doing things by halves.", when = { season = "autumn" } },
            { t = "Some trees let go a leaf at a time, all season, with a great deal of sighing. I prefer to decide, then let go.", when = { season = "autumn" } },
            { t = "Winter. Bare as a hat stand. I am resting. Resting and stopping are different things. Ask anyone old.", when = { season = "winter" } },
            { t = "Cold. I have been through ice ages, so this is mostly a nuisance. Read where the warm is.", when = { season = "winter" } },
            { t = "A clear sky. The same sky my family grew under while the great lizards stamped about. They were loud. You are better company.", when = { weather = "clear" } },
            { t = "Not a cloud. Full sun on every fan. On days like this I am almost talkative. Almost.", when = { weather = "clear" } },
            { t = "Grey sky, still air. A quiet day. I have had a great many and never tired of one.", when = { weather = "cloudy" } },
            { t = "Clouds. They pass. I have watched clouds pass for a very long time, and they always do.", when = { weather = "cloudy" } },
            { t = "Rain. The drops run down my fans and off the edges. My leaves had this worked out before umbrellas. Before hands.", when = { weather = "rain" } },
            { t = "Rain on the old wood. I drink slowly and think slowly. You may read at any speed you please.", when = { weather = "rain" } },
            { t = "Snow on the branches. I wear snow well. Old trees have had the practice.", when = { weather = "snow" } },
            { t = "White everywhere and very quiet. A tree in snow is a long sentence with no full stop. I am in no hurry to finish.", when = { weather = "snow" } },
            { t = "Mist. The garden has gone soft at the edges. I have stood in older mists, over swamps where nothing yet had flowers.", when = { weather = "mist" } },
            { t = "Fog. I cannot see the gate. I need not. You always come by the same path.", when = { weather = "mist" } },
        },
        tap = {
            "Hm. A tap on the bark. I felt that, in my own time.",
