        level = {
            { t = "I have begun to know your footstep. In my life, few footsteps have been worth learning.", when = { level = 2, max_level = 2 } },
            { t = "You sit on the same side of the trunk now. I have arranged a little extra shade there. Slowly.", when = { level = 2, max_level = 2 } },
            { t = "I took you for a passing visitor. I have revised the opinion. I revise opinions perhaps once a century.", when = { level = 2, max_level = 2 } },
            { t = "I will tell you something. I do not much like the wind. I bear the wind. I like you.", when = { level = 3, max_level = 3 } },
            { t = "When you read here, I stop counting time. Strange, for a tree whose whole trade is counting.", when = { level = 3, max_level = 3 } },
            { t = "An old monk once read under my branches. You turn a page the same way. I had forgotten that I missed him.", when = { level = 3, max_level = 3 } },
            { t = "I have outlived everyone who ever swept my leaves. I say so plainly, so you know what you mean to me.", when = { level = 4, max_level = 4 } },
            { t = "A secret: I am less patient than I look. When you are late, I lean toward the gate. Nobody can tell. Now you can.", when = { level = 4, max_level = 4 } },
            { t = "My veins fork and never join. I took that for the rule of everything. You are the exception.", when = { level = 4, max_level = 4 } },
            { t = "My family has spent two hundred million years learning to need nothing. I find I need you to come by. Remarkable.", when = { level = 5, max_level = 5 } },
