    beats = {
        { id = "seed", at = 15, title = "The heap",
            text = "I began as a seed beneath a temple tree. Her seeds smelled, frankly, of rancid butter, and so did I. The monks swept us into heaps. One young monk picked me out of the heap. I never learned why. I have had a long time to wonder." },
        { id = "fan", at = 40, title = "Two lobes",
            text = "My first leaf came up as a small green fan, split down the middle. Every vein forked and none joined. I decided then how I would grow. I have not changed my mind since, and I am not known for changing my mind." },
        { id = "stone", at = 80, title = "The stone",
            text = "When I was young, a child brought the monk a stone from the hills with a leaf pressed into the rock. My leaf. Fan, fork, notch. Older than the temple, older than the hills. So I had been here before. Some news takes a century to digest." },
        { id = "carriers", at = 140, title = "The carriers",
            text = "Long before any temple, some creature carried our seeds far and wide. A large one, with a taste for them. Nobody now remembers who. I have asked the wind. The wind keeps no records. I miss them anyway, whoever they were." },
        { id = "reader", at = 220, title = "Aloud",
            text = "The young monk grew old under my branches. Each evening he read aloud: sutras, poems, once a long tale of a monkey who made trouble in heaven. He turned the pages slowly. I knew the sound of a page long before I knew your name." },
        { id = "gold", at = 320, title = "One night of gold",
            text = "The autumn the old monk stopped coming out to read, my leaves turned, and in one night every leaf came down over his reading stone. The novices said I had dressed the courtyard for him. I do the same every year. That year, I meant the gesture." },
        { id = "fire", at = 450, title = "The fire",
            text = "Much later a great fire came through the city. The temple burned, and I burned with the temple, black to the top. Everyone said the old tree was finished. In spring I put out leaves from the charred wood. I do not talk about the fire. I have now." },
        { id = "cutting", at = 600, title = "The cutting",
            text = "After the fire a gardener took a cutting from me: one twig, set in sand in a clay pot. That twig is me. Or I am the twig. Or both of us are the old tree. I have considered this for a century and reached no firm conclusion." },
        { id = "street", at = 800, title = "The street",
            text = "The twig became a young tree and lived for years in a city street, among smoke and buses. My kind does well in cities. Nobody reads under a street tree, though. I counted feet instead of pages, and found I missed the pages." },
        { id = "garden", at = 1050, title = "Your garden",
            text = "Then I was lifted, roots in a sack, and brought here. You sat down under a tree barely taller than you and opened a book. Nobody had read beneath my branches since the old monk. I said nothing for a whole season. I was busy listening." },
        { id = "forks", at = 1400, title = "Forks",
            text = "My veins fork and never join. For ages I took that as the rule: every path parts, and stays parted. Then you came, and {total} pages later we are still side by side. I have revised the rule. I do not revise rules lightly." },
        { id = "all_at_once", at = 1800, title = "All at once",
            text = "I have outlasted every reader I ever knew. That was never the hard part. The hard part is how much I want the next page. One autumn night I will cover your chair in gold. Read on, sapling. I have time, and for once I want to share the time." },
    },
}
